        *{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.topbar{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:1020}.brand-mark{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,var(--brand),#8b5cf6);display:grid;place-items:center;color:#fff}.page-shell{max-width:1500px;margin:auto;padding:24px 24px 44px}.eyebrow{color:var(--brand);font-size:.7rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.page-title{font-weight:750;letter-spacing:-.035em}.subtext{font-size:.74rem;color:var(--muted)}.soft-btn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:10px;padding:.55rem .8rem;font-size:.85rem;font-weight:600}.summary-pill,.status-badge{display:inline-flex;align-items:center;gap:5px;border-radius:999px;font-weight:700}.summary-pill{padding:7px 11px;font-size:.76rem}.status-badge{padding:5px 8px;font-size:.66rem}.available{background:#e8f8f1;color:#087d55}.checked{background:#fff5dc;color:#a06600}.occupied{background:#efefff;color:#4646b8}.search-panel{max-width:720px;position:relative}.search-panel .form-control{padding-left:44px;min-height:50px;background:#fff;box-shadow:0 5px 18px rgba(32,41,64,.04)}.search-icon{position:absolute;left:16px;top:14px;color:var(--muted);z-index:2}.search-results{position:absolute;z-index:1010;left:0;right:0;top:56px;background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 18px 45px rgba(32,41,64,.16);max-height:430px;overflow:auto}.search-result{display:flex;width:100%;align-items:center;justify-content:space-between;gap:12px;padding:12px 15px;border-bottom:1px solid #eff1f5;background:#fff}.search-result-actions{display:flex;align-items:center;gap:6px;flex:none}.room-highlight{animation:roomFocus 2.2s ease}@keyframes roomFocus{0%,55%{box-shadow:0 0 0 4px #5b5bd633;border-color:var(--brand)}100%{box-shadow:0 5px 18px rgba(32,41,64,.04)}}.room-card{height:100%;background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:0 5px 18px rgba(32,41,64,.04);overflow:hidden;transition:.2s}.room-card:hover{transform:translateY(-2px);border-color:#d7d9f8;box-shadow:0 10px 25px rgba(32,41,64,.08)}.room-card.is-out{border-color:#f0cf85}.room-body{padding:15px}.room-icon{width:34px;height:34px;border-radius:10px;background:#efefff;color:var(--brand);display:grid;place-items:center;flex:none}.is-out .room-icon{background:#fff5dc;color:#a06600}.holder{min-height:58px;background:#fafbfc;border:1px solid #eff1f5;border-radius:10px;padding:10px 11px;font-size:.85rem}.card-actions{display:grid;grid-template-columns:1fr auto;gap:7px}.card-actions .btn{min-height:35px;border-radius:9px;font-size:.76rem;font-weight:700}.member-button{grid-column:1/-1;color:#4646b8;background:#f2f2ff;border:1px solid #ddddfa}.member-button:hover{background:#e8e8ff;color:#39399b}.form-control,.form-select{border-color:var(--line);border-radius:11px;min-height:43px}.form-control:focus,.form-select:focus{border-color:#aaaaf1;box-shadow:0 0 0 .22rem #5b5bd615}.btn-brand{background:var(--brand);border-color:var(--brand);color:#fff}.btn-brand:hover{background:#4646b8;border-color:#4646b8;color:#fff}.history-link{color:var(--brand);border:1px solid var(--line)!important;text-decoration:none;white-space:nowrap}.history-link:hover{background:#f6f6ff;color:#4646b8}.modal-content{border:0;border-radius:20px;box-shadow:0 30px 80px #17203333}.activity-drawer{width:min(620px,100vw)!important;border:0}.activity-drawer .offcanvas-header{padding:24px;border-bottom:1px solid var(--line);background:linear-gradient(135deg,#fafaff,#fff)}.activity-drawer .offcanvas-body{padding:24px;background:#f8f9fc}.audit-entry{position:relative;background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px;margin-bottom:16px;box-shadow:0 6px 20px rgba(32,41,64,.04)}.audit-entry:before{content:"";position:absolute;left:-7px;top:22px;width:13px;height:13px;border-radius:50%;background:var(--brand);border:3px solid #e7e7ff}.audit-meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.audit-detail{background:#f8f9fc;border-radius:10px;padding:10px}.audit-detail label{display:block;font-size:.67rem;font-weight:800;text-transform:uppercase;color:var(--muted);margin-bottom:3px}.audit-status{display:inline-flex;align-items:center;border-radius:999px;padding:6px 10px;font-size:.72rem;font-weight:750}.audit-returned{background:#e8f8f1;color:#087d55}.audit-out{background:#fff5dc;color:#a06600}.member-entry{background:#fff;border:1px solid var(--line);border-radius:14px;padding:15px;margin-bottom:12px}.member-exited{opacity:.68}@media(max-width:767px){.page-shell{padding:18px 12px}.top-actions .label{display:none}.audit-meta{grid-template-columns:1fr}.search-result{align-items:flex-start;flex-direction:column}.search-result-actions{width:100%}.search-result-actions .btn{flex:1}}
